const q=(id,question,options,answer,explanations,hint)=>({id,question,options,answer,explanations,hint});
export const cards=[
 {id:1,title:'皇帝留下的時間謎題',type:'故事與觀察',act:'第一道謎題｜快與慢',question:'同樣是化學反應，為什麼有些一瞬間，有些卻要很久？',goal:'用單位時間的變化量描述反應速率。',opening:'製鹽任務完成後，皇帝履行承諾，讓兩人返回現代。離別前，他送來一只木匣。小葵打開它：裡面是一只沙漏，還有三則文言小箋。阿公說：「先別急著猜意思，我們用實驗找線索。」',dialogue:['阿公，火柴一下就燒完，鐵釘卻要好久才生鏽？','先找可以測量的變化，再問：相同時間裡，變了多少？'],expressions:['wonder','gentle'],scene:1,prediction:'怎樣比較兩次反應的快慢才有意義？',choices:['只看最後得到多少產物','比較相同時間內的變化量','我還不確定，想先看看'],required:['scale'],labels:['比較四種反應的時間尺度'],conceptTitle:'速率，描述變化有多快',points:['反應速率是單位時間內反應物減少，或生成物增加的量。','例如 20 秒收集 100 mL 氣體，這段時間的平均速率是 100 ÷ 20＝5 mL/s。','比較時要說清楚測量對象與條件；最後有多少產物，是另一個問題。'],equation:'平均速率＝變化量 ÷ 經過時間',bridge:'如果材料相同，有什麼方法可以讓反應變快？',quiz:q('c1','反應速率主要描述什麼？',['反應物原來的重量','單位時間內反應物或生成物的變化','最終產物一定有多少'],1,['重量是起始條件，沒有時間就不能描述快慢。','對，速率一定涉及變化量與時間。','產量是最後的總量；速率說明累積得多快。'],'看時間尺：相同產量可以花不同的時間。')},
 {id:2,title:'反應速度調查室',type:'操作 01',act:'第一道謎題｜快與慢',question:'同樣質量的碳酸鈣，變細以後反應就會更快嗎？',goal:'比較接觸面積、濃度，並固定其他變因。',opening:'阿公把兩份等重的碳酸鈣放上天平。小葵把其中一份磨細，再準備相同的稀鹽酸。沙漏旁的第一道謎題，終於有了調查方向。',dialogue:['磨細以後，只是變小，沒有多出材料呀！','很好。固定質量與酸量，讓生成的氣體替我們回答。'],expressions:['curious','thoughtful'],scene:2,prediction:'相同質量、酸足量且其他條件相同，哪一份較快？',choices:['塊狀','粉末狀','兩者必定一樣快','還不確定'],required:['surface','concentration'],labels:['用足量酸，比較同質量的塊狀與粉末','固定顆粒與質量，比較兩種足量酸濃度'],conceptTitle:'碰得到的表面多了，碰撞的機會也多了',points:['同質量的粉末總表面積較大，酸能同時接觸更多反應表面。','提高濃度，單位體積內的反應粒子較多，通常提高碰撞機會。','一次只改一個變因。酸不足時，反應可能更早停止，最後氣體總量也會較少。'],equation:'CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂',bridge:'為什麼只是磨細、提高濃度，就會讓反應變快？',quiz:q('c2','相同質量、其他條件相同，哪種碳酸鈣通常反應較快？',['塊狀','粉末狀','一定一樣快'],1,['塊狀的總接觸面積較小；請比較兩條初期曲線。','粉末有較大的總接觸面積，不是因為它的質量變多。','質量相同不代表總接觸面積相同。'],'查看同質量的兩筆紀錄，先比較曲線前段。')},
 {id:3,title:'看不見的粒子碰撞',type:'動畫與圖解',act:'第一道謎題｜快與慢',question:'每一次碰撞，都能讓粒子發生反應嗎？',goal:'用有效碰撞解釋濃度、表面積與反應物本性。',opening:'小葵把實驗紀錄放到顯微模擬器旁。畫面中的粒子不停運動，有些碰撞後分開，有些才留下反應的閃光。',dialogue:['它們一直碰到，為什麼不是每次都反應？','要有合適的碰撞條件。不同材料，也有不同的反應本性。'],expressions:['thinking','mentor'],prediction:'把同體積內的反應粒子增加，通常會怎樣？',choices:['碰撞機會增加','每一次碰撞都必定成功','還不確定'],required:['collision','nature'],labels:['比較濃度與可接觸表面','比較鎂、鋅、銅對相同稀鹽酸的反應'],conceptTitle:'碰撞機會，和有效碰撞要分開想',points:['有效碰撞是能導致反應的碰撞；不是每次碰撞都成功。','濃度較高、接觸面積較大，通常增加碰撞的機會。','相同酸、溫度與相近表面積下，鎂較快、鋅較慢；銅在這裡不會排出氫氣。這是反應物本性的差別。'],equation:'碰到 ≠ 一定反應',bridge:'如果提高溫度，粒子更快移動，反應會怎麼變？',quiz:q('c3','提高濃度通常讓反應較快，主要原因是？',['每顆粒子一定變大','單位體積的反應粒子增加，碰撞機會通常提高','所有碰撞都變成有效碰撞'],1,['濃度增加不是粒子體積變大，而是單位體積中粒子較多。','正確。更多碰撞機會，通常帶來更多有效碰撞。','碰撞是否有效仍要看能量與合適的條件。'],'比較低濃度與高濃度畫面的粒子數。')},
 {id:4,title:'冷與熱的反應競賽',type:'操作 02',act:'第一道謎題｜快與慢',question:'只改變溫度，可以讓同一個反應更快嗎？',goal:'比較溫度對速率與最終理論產量的影響。',opening:'小葵準備兩套完全相同的反應裝置，一套維持 20°C，另一套放進溫水浴。這次，她決定只改變溫度。',dialogue:['熱的那瓶先跑到終點！終點也會變高嗎？','看前段速度，也要等到兩瓶都反應完。'],expressions:['surprised','confident'],prediction:'其他條件相同，40°C 與 20°C 完全反應後會怎樣？',choices:['40°C 較快，理論總量相同','40°C 必定得到兩倍產物','還不確定'],required:['warm'],labels:['比較 20°C 與較高溫度，記錄相同的最終量'],conceptTitle:'升溫，通常讓有效碰撞更容易發生',points:['溫度升高，粒子的平均動能增加；通常讓有效碰撞的比例提高。','本模型中，相同初始反應物完全反應，最後 CO₂ 理論總量相同。','圖中體積一律換算至同一參考條件；不能把氣體熱脹冷縮誤認為反應變快。'],equation:'反應更快 ≠ 原子變多',bridge:'不用升溫，還有別的方法能加快反應嗎？',quiz:q('c4','其他條件不變，提高溫度通常會：',['加快反應','使所有反應停止','必定增加兩倍產物'],0,['對，通常提高有效碰撞的機會。','較高溫度通常使粒子運動更快，而不是停止。','起始材料相同，完全反應的理論產量不會憑空增加。'],'看兩條曲線誰先到達共同的平台。')},
 {id:5,title:'神祕的催化劑',type:'操作 03',act:'第二道謎題｜快不等於多',question:'二氧化錳讓氣泡變多了，它自己變成氧氣了嗎？',goal:'認識催化劑、反應途徑與速率的關係。',opening:'阿公取出雙氧水與少量黑色二氧化錳。加入二氧化錳的瓶子，很快冒出許多氣泡。小葵盯著瓶底的黑色粉末。',dialogue:['黑色粉末是不是變成氧氣，才有這麼多泡泡？','比較反應前後的粉末，再看兩瓶最後各有多少氧氣。'],expressions:['wonder','idea'],scene:3,prediction:'加入適當催化劑，反應完全後的氧氣總量會怎樣？',choices:['必定變多','相同雙氧水量下，理論總量相同','還不確定'],required:['catalyst'],labels:['比較有、無催化劑，觀察粉末前後狀態與總量'],conceptTitle:'換一條比較容易通過的反應路徑',points:['催化劑提供另一條反應途徑，降低所需跨越的能量障礙，通常加快反應。','催化劑可能參與反應過程，但在整體反應中通常不被淨消耗。二氧化錳不是氧氣的來源。','相同初始雙氧水完全分解，理論氧氣總量不因催化劑而增加。酵素是生物催化劑，也有合適的作用條件。'],equation:'2H₂O₂ → 2H₂O + O₂　（MnO₂ 催化）',bridge:'所以反應更快，真的不代表最後能得到更多產物？',quiz:q('c5','加入適當催化劑後，下列何者正確？',['反應速率可能增加','催化劑一定完全變成產物','產物一定增加十倍'],0,['對。催化劑改變反應途徑，通常提高速率。','催化劑通常不被淨消耗，不是拿來增加反應物的材料。','產量受反應物供應限制；催化劑不會創造原子。'],'比較兩條曲線的平台，以及反應後的黑色粉末。')},
 {id:6,title:'反應快，不代表產量多',type:'圖表與練習',act:'第二道謎題｜快不等於多',question:'曲線比較陡，代表最後一定能收集更多氣體嗎？',goal:'分清曲線斜率、平均速率與平台值。',opening:'小葵把剛剛的實驗曲線疊在一起。不同的線先後爬上平台，有些終點卻在同一個高度。她在紙條第三句旁畫了一顆星。',dialogue:['原來「多快到達」與「最後有多少」，要分開看！','沒錯。前段斜率告訴你快慢，最後的平台才是總量。'],expressions:['excited','encourage'],prediction:'兩條曲線最後停在同一個高度，但甲較早到達，代表？',choices:['甲較快、最後總量相同','甲的產物一定較多','還不確定'],required:['chart'],labels:['讀取實驗紀錄的斜率與平台'],conceptTitle:'看斜率問快慢，看平台問總量',points:['累積生成量－時間曲線越陡，該段時間的速率越大。平均速率用兩點的變化量除以時間差。','平台表示累積量暫時不再增加；單向反應的材料用完，不能稱為動態平衡。','只有起始反應物及限制條件合適時，改變溫度、表面積或催化劑才可能只改變快慢、保持理論產量。'],equation:'甲：100 ÷ 20＝5 mL/s　｜　乙：100 ÷ 60≈1.67 mL/s',bridge:'有些反應可以朝相反方向進行，那它們的終點又是什麼？',quiz:q('c6','甲 20 秒、乙 60 秒都收集到最終 100 mL（同一測量條件）。何者正確？',['甲較快，最終量相同','乙最後一定比較多','甲的最終量是乙的三倍'],0,['甲達到相同總量所需時間較短，所以這段平均速率較大。','兩者最終都是 100 mL，時間長不代表總量多。','三倍的是這段平均速率，不是最終生成量。'],'分別計算 100÷20 與 100÷60。')},
 {id:7,title:'可以倒轉的化學反應？',type:'故事與動畫',act:'第三道謎題｜靜止的祕密',question:'生成物，有可能再變回反應物嗎？',goal:'辨認正反應、逆反應與可逆反應。',opening:'阿公指著紙條的第二句：「水面雖平，潛流未歇。」他先讓小葵觀察密閉水瓶，再打開真正的化學反應模擬器。',dialogue:['水蒸發又凝結，這也是化學反應嗎？','那是物理類比。接下來的 NO₂ 與 N₂O₄，才有不同物質互相轉換。'],expressions:['thinking','mentor'],scene:4,prediction:'可逆反應的兩個方向能同時進行嗎？',choices:['可以，在適當條件下同時進行','一定要等正反應結束才有逆反應','還不確定'],required:['reverse'],labels:['比較物理類比與真正的可逆化學反應'],conceptTitle:'雙向箭號，記錄兩個方向',points:['依書寫方向，左邊變右邊叫正反應；右邊變左邊叫逆反應。','⇌ 表示適當條件下兩個方向都能進行，也可能同時發生。','水蒸發與凝結都還是 H₂O，是物理變化；NO₂ 轉成 N₂O₄ 則是化學反應。NO₂ 紅棕色，N₂O₄ 近乎無色。'],equation:'2NO₂(g) ⇌ N₂O₄(g)',bridge:'兩種方向都在進行，為什麼瓶子的顏色有時不再改變？',quiz:q('c7','可逆反應代表什麼？',['適當條件下正、逆反應都可以進行','只能先完全向右、再完全向左','只是粒子向左右移動，沒有化學變化'],0,['正確。兩個反應方向可以同時存在。','兩個方向可以同時進行，不必輪流等待。','反應方向是物質間的轉換，不是粒子移動的方向。'],'比較 ⇌ 兩側的物質種類。')},
 {id:8,title:'永不停止的平衡',type:'操作 04',act:'第三道謎題｜靜止的祕密',question:'顏色不再變了，反應真的停止了嗎？',goal:'用正逆速率相等解釋動態平衡。',opening:'密閉瓶的顏色逐漸穩定，小葵差點關掉模擬器。阿公提醒她切到微觀視角，再看看兩個方向的速率。',dialogue:['顏色一樣，濃度也沒什麼變，還在反應？','把兩個方向一起打開看。穩定的外表，可能來自持續的交換。'],expressions:['surprised','thoughtful'],prediction:'達到化學平衡時，哪件事會發生？',choices:['兩個方向都停止','兩個方向以相同速率持續進行','兩種物質濃度一定一樣','還不確定'],required:['equilibrium','micro'],labels:['觀察兩個非零速率趨於相等','切換微觀視角，看平衡時的雙向轉換'],conceptTitle:'一樣快，所以整體不再累積改變',points:['在密閉且條件固定的系統中，正、逆反應速率相等時，可建立動態平衡。','兩個方向都持續反應；宏觀濃度與顏色保持穩定。','NO₂ 與 N₂O₄ 的濃度不必相等。「速率相等」不是「濃度相等」。'],equation:'正反應速率＝逆反應速率 ≠ 0',bridge:'如果加入更多 NO₂，或改變溫度，原來的平衡會怎樣？',quiz:q('c8','達到化學平衡時：',['所有反應完全停止','正、逆反應速率相等','反應物與生成物濃度一定相等'],1,['請看微觀視角：雙向轉換仍然存在。','對。兩方向持續且一樣快，所以濃度穩定。','濃度通常不同；相等的是正、逆反應速率。'],'讀取平衡時兩個速率與兩個濃度。')},
 {id:9,title:'打破平衡的挑戰',type:'操作 05',act:'第三道謎題｜靜止的祕密',question:'已達平衡的系統，能被新的條件改變嗎？',goal:'分清濃度、溫度與催化劑對平衡的影響。',opening:'小葵提出最後的挑戰：讓已穩定的瓶子再度改變。阿公把溫控器、NO₂ 定量注入器與催化比較模型交給她。',dialogue:['如果加熱更快，那最後也會有更多 N₂O₄ 嗎？','這次要同時看速度與平衡位置，它們可能朝不同方向改變。'],expressions:['determined','confident'],prediction:'生成 N₂O₄ 是放熱方向。升溫時平衡通常偏向哪邊？',choices:['較多 NO₂ 的方向','較多 N₂O₄ 的方向','催化劑會決定最後比例','還不確定'],required:['add','heat','cool','cat'],labels:['注入 NO₂，觀察瞬間跳升與重新平衡','升溫至 40°C，建立新平衡','降溫至 10°C，建立新平衡','比較有、無假想催化劑到達相同平衡'],conceptTitle:'改變平衡位置，和縮短等待時間是兩件事',points:['固定溫度與體積增加 NO₂，瞬間先改變 NO₂ 濃度，接著正反應較快，直到建立新平衡。','正方向放熱：升溫有利吸熱的逆方向，NO₂ 比例提高、顏色加深；降溫則相反。','理想催化劑同時加快正、逆方向，縮短接近平衡的時間；固定溫度下不改變最終平衡組成。'],equation:'2NO₂(g) ⇌ N₂O₄(g) + 熱',bridge:'現在，用實驗證據重新解讀皇帝留下的三句話吧。',quiz:q('c9','對正方向放熱的可逆反應升溫，平衡通常：',['偏向吸熱的逆反應方向','必定增加放熱方向的產物','停止反應'],0,['正確。此處偏向 NO₂，顏色加深。','升溫可能加快兩方向，卻不代表最後生成較多放熱產物。','新的條件打破原平衡，系統會重新建立平衡。'],'比較 10°C、25°C、40°C 的 NO₂ 最終濃度。')},
 {id:10,title:'時間煉金術的真相',type:'結局與最終挑戰',act:'終章｜用證據解開謎題',question:'我們能用哪些實驗證據，重新解讀皇帝的三則小箋？',goal:'整合反應速率、產量與化學平衡。',opening:'小葵重新攤開紙條。沙漏中的細砂仍在落下，這次她已知道：沒有時間魔法，只有可以觀察、比較與解釋的規律。',dialogue:['原來反應快慢，跟最後能得到多少產物，是不同的問題！','沒錯。看起來沒有變化，也不代表裡面真的停止了。'],expressions:['excited','encourage'],scene:5,prediction:'工業製氨，為什麼不能只把溫度調到最高？',choices:['要兼顧反應速度與平衡時的產物比例','溫度越高一定什麼都更好','還不確定'],required:['truth'],labels:['把三道謎題與證據連起來'],conceptTitle:'加快過程，不一定改變最後的結果',points:['反應物本性、濃度、表面積、溫度與催化劑，都可能影響反應速率。','動態平衡是持續的雙向反應；巨觀穩定不代表微觀停止。','工業製氨的正方向放熱。升溫通常加快速率，但不利平衡時的氨比例，因此要兼顧速度與產物比例；催化劑能協助加快達到平衡。'],equation:'N₂ + 3H₂ ⇌ 2NH₃ + 熱',bridge:'「原來古人的觀察，也能用我們做的實驗來解讀！」小葵把答案寫進科學手札。',quiz:q('c10','製氨時使用適當催化劑，主要是為了？',['固定溫度下加快接近平衡','固定溫度下改變最終平衡比例','創造更多氮原子'],0,['催化劑縮短等待時間，工業仍要選擇合適條件。','催化劑同時加快兩方向，不改變固定溫度下的平衡組成。','原子守恆；催化劑不會創造氮原子。'],'回想第 09 卡的催化劑比較。')}
];

