export const glossary=[['反應速率','單位時間內反應物減少或生成物增加的量。例：每秒生成 3 mL 氣體。'],['控制變因','比較時保持不變的條件；操作變因是刻意改變的因素。'],['有效碰撞','能導致化學反應的碰撞，不是每次碰撞都有效。'],['接觸面積','反應物能互相接觸的總表面；同質量粉末通常比塊狀大。'],['催化劑','改變反應途徑、通常不被整體反應淨消耗的物質。'],['活化能','讓反應能發生而需要跨越的能量障礙；此章只做定性理解。'],['可逆反應','適當條件下正、逆方向都能進行的化學反應，用 ⇌ 表示。'],['動態平衡','正逆反應速率相等且持續，宏觀組成穩定的狀態。'],['平衡移動','條件改變後，系統形成不同平衡組成的過程。'],['理論產量','依反應物供應與反應式，在指定假設下能生成的最大量。']];
